let count = 0;
function f() { count++; return count; }
return f(...[]);

function f(a, b) { return a * 10 + b; }
let iterable = {[Symbol.iterator]() { let index = 0; return {next() { index++; return index === 1 ? {done: false, value: 7} : (index === 2 ? {done: false, value: 8} : {done: true}); }}; }};
return f(...iterable);

function Point(x, y) { this.x = x; this.y = y; }
let p = new Point(...[3, 4]);
return p.x * 10 + p.y;

let closed = false;
function f() {}
let iterable = {[Symbol.iterator]() { return {next() { throw new Error("boom"); }, return() { closed = true; return {done: true}; }}; }};
try { f(...iterable); } catch (e) { return e.message === "boom" && closed; }

let message = "";
try { (42)(...[1]); } catch (e) { message = e.message; }
return message;

let message = "";
function f() {}
try { f.apply(null, 42); } catch (e) { message = e.message; }
return message;

function f(a, b) { return a * 10 + b; }
let arrayLike = {length: 2, 0: 5, 1: 6};
return f.apply(null, arrayLike);

let order = "";
function mark(name) { order += name; return name; }
function f() { return order; }
return f(mark("a"), ...[mark("b")], mark("c"));

let message = "";
function f() {}
try { f(...42); } catch (e) { message = e.message; }
return message;
